#!/usr/bin/env python3
"""Measure the algebra generated by split norm-system Hessians."""

from itertools import combinations
import json
from pathlib import Path

from sympy import Integer, Poly, symbols

from binary_split_norm_control import product_from_roots
from interpolation_projection_control import matrix_multiply
from multisection_span_control import section_basis
from principal_minor_update_algebra import generated_algebra, subtract
from signed_hankel_minrank import rank_mod
from toy_jacobian import GenusTwo


PRIME = 101


def quadratic_form_matrix(polynomial, variables, prime):
    coefficients = polynomial.as_dict()
    size = len(variables)
    matrix = [[0] * size for _ in range(size)]
    inverse_two = pow(2, -1, prime)
    for row in range(size):
        exponent = [0] * size
        exponent[row] = 2
        matrix[row][row] = int(coefficients.get(tuple(exponent), 0)) % prime
        for column in range(row + 1, size):
            exponent = [0] * size
            exponent[row] = 1
            exponent[column] = 1
            value = int(coefficients.get(tuple(exponent), 0)) % prime
            matrix[row][column] = value * inverse_two % prime
            matrix[column][row] = matrix[row][column]
    return matrix


def panel_equations(curve, panel):
    poly = curve.poly
    r = panel["projective_section_dimension"]
    u = tuple(panel["target_u"])
    v = tuple(panel["target_v"])
    fixed = (r - 1) // 2 if r % 2 else r
    basis = section_basis(poly, u, v, r)
    variables = symbols(f"z0:{r}")
    parameters = []
    cursor = 0
    for index in range(r + 1):
        if index == fixed:
            parameters.append(Integer(1))
        else:
            parameters.append(variables[cursor])
            cursor += 1

    coefficients = [Integer(0)] * (r + 3)
    for i, (bi, ai) in enumerate(basis):
        for j, (bj, aj) in enumerate(basis):
            numerator = poly.sub(
                poly.mul(poly.mul(bi, bj), curve.coefficients),
                poly.mul(ai, aj),
            )
            quotient = poly.exact_quotient(numerator, u)
            for degree, value in enumerate(quotient):
                coefficients[degree] += parameters[i] * parameters[j] * value

    leading = int(coefficients[-1]) % curve.p
    assert leading in (1, curve.p - 1)
    if leading == curve.p - 1:
        coefficients = [-value for value in coefficients]
    expected = product_from_roots(poly, panel["split_abscissae"])
    equations = [
        Poly(coefficients[index] - expected[index], *variables, modulus=curve.p)
        for index in range(r + 2)
    ]
    substitution = dict(zip(variables, panel["planted_parameters"], strict=True))
    assert all(int(equation.as_expr().subs(substitution)) % curve.p == 0
               for equation in equations)
    return variables, equations


def analyze(curve, panel):
    variables, equations = panel_equations(curve, panel)
    size = len(variables)
    matrices = [
        quadratic_form_matrix(equation, variables, curve.p)
        for equation in equations
    ]
    matrices = [matrix for matrix in matrices if any(map(any, matrix))]
    flattened = [[value for row in matrix for value in row] for matrix in matrices]
    algebra_dimension, closure_rounds = generated_algebra(matrices, curve.p)
    prefix_dimensions = [
        generated_algebra(matrices[:length], curve.p)[0]
        for length in range(1, len(matrices) + 1)
    ]
    first_full_prefix = next(
        (
            index + 1
            for index, dimension in enumerate(prefix_dimensions)
            if dimension == size * size
        ),
        None,
    )
    noncommuting = sum(
        any(
            value
            for row in subtract(
                matrix_multiply(left, right, curve.p),
                matrix_multiply(right, left, curve.p),
                curve.p,
            )
            for value in row
        )
        for left, right in combinations(matrices, 2)
    )
    return {
        "projective_section_dimension": size,
        "quadratic_coefficient_equations": len(matrices),
        "hessian_linear_span_dimension": rank_mod(flattened, curve.p),
        "symmetric_matrix_space_dimension": size * (size + 1) // 2,
        "unital_hessian_algebra_dimension": algebra_dimension,
        "full_matrix_algebra_dimension": size * size,
        "hessians_generate_full_matrix_algebra": algebra_dimension == size * size,
        "product_closure_rounds": closure_rounds,
        "natural_prefix_algebra_dimensions": prefix_dimensions,
        "first_full_natural_prefix": first_full_prefix,
        "noncommuting_hessian_pairs": noncommuting,
        "hessian_pairs": len(matrices) * (len(matrices) - 1) // 2,
    }


def main():
    source = json.loads(
        Path(__file__).with_name("binary_split_norm_control.json").read_text()
    )
    curve = GenusTwo(PRIME)
    result = {
        "prime": PRIME,
        "genus": 2,
        "panels": [analyze(curve, panel) for panel in source["panels"]],
    }
    print(json.dumps(result, indent=2, sort_keys=True))


if __name__ == "__main__":
    main()
